formulas.rawText:
{
  "originalFormula": "Amount \, of \, phosphorus = \\frac{5.63 \\times 10^{20} \, \\text{atoms} \\times 30.975 \, \\text{g/mole}}{6.023 \\times 10^{23} \, \\text{atoms/mole}} = 28.95 \, \\text{g}",
  "genericFormula": "Amount \, of \, phosphorus = \\frac{N \times M}{N_A}",
  "description": "Esta fórmula calcula a quantidade de fósforo em gramas a partir do número de átomos de fósforo, utilizando a massa molar do fósforo e a constante de Avogadro. Ela nos permite entender como converter uma quantidade de átomos em uma medida de massa, que é mais prática para aplicações em química.",
  "concepts": [
    "Massa molar",
    "Número de Avogadro",
    "Conversão de unidades",
    "Quantidade de substância"
  ],
  "symbols": [
    {
      "symbol": "N",
      "description": "Representa o número de átomos de fósforo que estamos considerando."
    },
    {
      "symbol": "M",
      "description": "Representa a massa molar do fósforo, que é a quantidade de gramas por mol de fósforo."
    },
    {
      "symbol": "N_A",
      "description": "Representa o número de Avogadro, que é a quantidade de átomos ou moléculas em um mol de qualquer substância, aproximadamente 6.022 x 10^23."
    }
  ]
}
